68: rule token = parse
69:   | '\n'
70:       { Lexing.new_line lexbuf; token lexbuf }
71:   | space+
72:       { token lexbuf }
73:   | "(*)"
74:       { Lexlib.backjump lexbuf 2; LEFTPAR }
75:   | "(*"
76:       { Lexlib.comment lexbuf; token lexbuf }
77:   | '_'
78:       { UNDERSCORE }
79:   | ident as id
80:       { try Hashtbl.find keywords id with Not_found -> IDENT id }
81:   | digit+ as i
82:       { INTEGER (int_of_string i) }
83:   | "<-"
84:       { LARROW }
85:   | "["
86:       { LEFTSQ }
87:   | "]"
88:       { RIGHTSQ }
89:   | "("
90:       { LEFTPAR }
91:   | ")"
92:       { RIGHTPAR }
93:   | "."
94:       { DOT }
95:   | ".."
96:       { DOTDOT }
97:   | ","
98:       { COMMA }
99:   | "'"
100:       { QUOTE }
101:   | "]" ("'"+ as s)
102:       { RIGHTSQ_QUOTE s }
103:   | ")" (['\'' '_'] ['a'-'z' 'A'-'Z'] idsuf* as s)
104:       { RIGHTPAR_QUOTE s }
105:   | op_char+ "'"* as op
106:       { OPERATOR op }
107:   | '"'
108:       { STRING (Lexlib.string lexbuf) }
109:   | "import" space* '"'
110:       { INPUT (Lexlib.string lexbuf) }
111:   | eof
112:       { EOF }
