260: let rec print_type info fmt ty = match ty.ty_node with
261:   | Tyvar s ->
262:       begin match info.info_version with
263:       | V20 -> unsupported "smtv2: you must encode type polymorphism"
264:       | V26 | V26Par -> print_tv info fmt s
265:       end
266:   | Tyapp (ts, l) ->
267:       begin match query_syntax info.info_syn ts.ts_name, l with
268:       | Some s, _ ->
269:         info.type_sorts <- Mstr.add s ts info.type_sorts;
270:         info.ty_tysymbol <- Mts.add ts ty info.ty_tysymbol;
271:         syntax_arguments s (print_type info) fmt l
272:       | None, [] -> print_ident info fmt ts.ts_name
273:       | None, _ -> fprintf fmt "(%a %a)" (print_ident info) ts.ts_name
274:           (print_list space (print_type info)) l
275:      end
