343: (* can the type of a value be derived from the type of the arguments? *)
344: let unambig_fs version fs =
345:   let rec lookup v ty = match ty.ty_node with
346:     | Tyvar u when tv_equal u v -> true
347:     | _ -> ty_any (lookup v) ty
348:   in
349:   let lookup v = List.exists (lookup v) fs.ls_args in
350:   let rec inspect ty = match ty.ty_node with
351:     | Tyvar u when not (lookup u) -> false
352:     | _ -> ty_all inspect ty
353:   in
354:   match version with
355:   | V20 -> true
356:   | V26 | V26Par ->  inspect (Option.get fs.ls_value)
