358: (** expr *)
359: let rec print_term info fmt t =
360:   debug_print_term "Printing term: " t;
361:   if check_for_counterexample t
362:   then
363:     begin match t.t_node with
364:     | Tapp (ls,_) ->
365:       info.info_model <- add_model_element (ls,t.t_loc,t.t_attrs) info.info_model
366:     | _ -> assert false (* cannot happen because check_for_counterexample is true *)
367:     end;
368: 
369:   begin
370:    let ty = t.t_ty in
371:     match ty with
372:     | None -> ()
373:     | Some ty ->
374:       match ty.ty_node with
375:       | Tyvar _ -> ()
376:       | Tyapp (ts, _) ->
377:     info.ty_tysymbol <- Mts.add ts ty info.ty_tysymbol
378:   end;
379: 
380:   check_enter_vc_term t info.info_in_goal info.info_vc_term;
381: 
382:   let () = match t.t_node with
383:   | Tconst c ->
384:       let ts = match t.t_ty with
385:         | Some ({ ty_node = Tyapp (ts, []) } as ty) ->
386:           info.ty_tysymbol <- Mts.add ts ty info.ty_tysymbol;
387:           ts
388:         | _ -> assert false (* impossible *) in
389:       (* look for syntax literal ts in driver *)
390:       begin match query_syntax info.info_rliteral ts.ts_name, c with
391:         | Some st, Constant.ConstInt c ->
392:           info.type_sorts <- Mstr.add st ts info.type_sorts;
393:           syntax_range_literal st fmt c
394:         | Some st, Constant.ConstReal c ->
395:           info.type_sorts <- Mstr.add st ts info.type_sorts;
396:           let fp = match ts.ts_def with
397:             | Float fp -> fp
398:             | _ -> assert false in
399:           syntax_float_literal st fp fmt c
400:         | _, Constant.ConstStr _
401:         | None, _ ->
402:             (* we must check here that the type is either ty_int or
403:                ty_real, otherwise it makes no sense to print the
404:                literal. This may happen since we can't ensure that
405:                preserved literal types are exactly those that have a
406:                dedicated syntax rule *)
407:             if ts_equal ts ts_int || ts_equal ts ts_real || ts_equal ts ts_str then
408:               Constant.print number_format escape fmt c
409:             else
410:               unsupportedTerm t
411:                 "smtv2: don't know how to print this literal, consider adding a syntax rule in the driver"
412:       end
413:   | Tvar v -> print_var info fmt v
414:   | Tapp (ls, tl) ->
415:     begin match query_syntax info.info_syn ls.ls_name with
416:       | Some s -> syntax_arguments_typed s (print_term info)
417:         (print_type info) t fmt tl
418:       | None -> begin match tl with (* for cvc3 wich doesn't accept (toto ) *)
419:           | [] ->
420: 
421:             let str_ls = sprintf "%a" (print_ident info) ls.ls_name in
422:             let cur_var = info.info_labels in
423:             let new_var = update_info_labels str_ls cur_var t ls in
424:             let () = info.info_labels <- new_var in
425:             let vc_term_info = info.info_vc_term in
426:             if vc_term_info.vc_inside then begin
427:               match vc_term_info.vc_loc with
428:               | None -> ()
429:               | Some loc ->
430:                 let attrs = (* match vc_term_info.vc_func_name with
431:                   | None -> *)
432:                     ls.ls_name.id_attrs
