476: and print_fmla info fmt f =
477:   debug_print_term "Printing formula: " f;
478:   if check_for_counterexample f
479:   then
480:     begin match f.t_node with
481:     | Tapp (ls,_) ->
482:       info.info_model <- add_model_element (ls,f.t_loc,f.t_attrs) info.info_model
483:     | _ -> assert false (* cannot happen because check_for_counterexample is true *)
484:     end;
485: 
486:   check_enter_vc_term f info.info_in_goal info.info_vc_term;
487: 
488:   let () = match f.t_node with
489:   | Tapp ({ ls_name = id }, []) ->
490:       print_ident info fmt id
491:   | Tapp (ls, tl) -> begin match query_syntax info.info_syn ls.ls_name with
492:       | Some s -> syntax_arguments_typed s (print_term info)
493:         (print_type info) f fmt tl
494:       | None -> begin match tl with (* for cvc3 wich doesn't accept (toto ) *)
495:           | [] ->
496:               print_ident info fmt ls.ls_name
497:           | _ -> fprintf fmt "@[<hv2>(%a@ %a)@]"
498:               (print_ident info) ls.ls_name
499:               (print_list space (print_term info)) tl
500:         end end
501:   | Tquant (q, fq) ->
502:       let q = match q with Tforall -> "forall" | Texists -> "exists" in
503:       let vl, tl, f = t_open_quant fq in
504:       (* TODO trigger dépend des capacités du prover : 2 printers?
505:       smtwithtriggers/smtstrict *)
506:       if tl = [] then
507:         fprintf fmt "@[<hv2>(%s @[<h>(%a)@]@ %a)@]"
508:           q
509:           (print_typed_var_list info) vl
510:           (print_fmla info) f
511:       else
512:         fprintf fmt "@[<hv2>(%s @[<h>(%a)@]@ (! %a %a))@]"
513:           q
514:           (print_typed_var_list info) vl
515:           (print_fmla info) f
516:           (print_triggers info) tl;
517:       List.iter (forget_var info) vl
518:   | Tbinop (Tand, f1, f2) ->
519:       fprintf fmt "@[<hv2>(and@ %a@ %a)@]" (print_fmla info) f1 (print_fmla info) f2
520:   | Tbinop (Tor, f1, f2) ->
521:       fprintf fmt "@[<hv2>(or@ %a@ %a)@]" (print_fmla info) f1 (print_fmla info) f2
522:   | Tbinop (Timplies, f1, f2) ->
523:       fprintf fmt "@[<hv2>(=>@ %a@ %a)@]"
524:         (print_fmla info) f1 (print_fmla info) f2
525:   | Tbinop (Tiff, f1, f2) ->
526:       fprintf fmt "@[<hv2>(=@ %a@ %a)@]" (print_fmla info) f1 (print_fmla info) f2
527:   | Tnot f ->
528:       fprintf fmt "@[<hv2>(not@ %a)@]" (print_fmla info) f
529:   | Ttrue ->
530:       pp_print_string fmt "true"
531:   | Tfalse ->
532:       pp_print_string fmt "false"
533:   | Tif (f1, f2, f3) ->
534:       fprintf fmt "@[<hv2>(ite %a@ %a@ %a)@]"
535:         (print_fmla info) f1 (print_fmla info) f2 (print_fmla info) f3
536:   | Tlet (t1, tb) ->
537:       let v, f2 = t_open_bound tb in
538:       fprintf fmt "@[<hv2>(let ((%a %a))@ %a)@]" (print_var info) v
539:         (print_term info) t1 (print_fmla info) f2;
540:       forget_var info v
541:   | Tcase(t, bl) ->
542:      print_tcase info t print_fmla fmt bl
543:   | Tvar _ | Tconst _ | Teps _ -> raise (FmlaExpected f) in
