547: and print_tcase info t pr fmt bl =
548:      let ty = t_type t in
549:      match ty.ty_node with
550:      | Tyapp (ts,_) when ts_equal ts ts_bool ->
551:         print_boolean_branches info t pr fmt bl
552:      | _ ->
553:         match info.info_version with
554:         | V20 | V26Par -> begin
555:             (* Use a chain of if-then-else constructs. *)
556:             match t.t_node with
557:             | Tvar v -> print_branches info v pr fmt bl
558:             | _ ->
559:                let subject = create_vsymbol (id_fresh "subject") (t_type t) in
560:                fprintf fmt "@[<hv2>(let ((%a @[%a@]))@ %a)@]"
561:                  (print_var info) subject (print_term info) t
562:                  (print_branches info subject pr) bl;
563:                forget_var info subject
564:           end
565:         | V26 ->
566:            fprintf fmt "@[<hv2>(match %a (@[<hv0>%a@]))@]"
567:              (print_term info) t
568:              (print_list space (print_match_branch info ty pr)) bl
569: 
570: and print_match_branch info ty pr fmt b =
571:   let (p,t) = t_open_branch b in
572:   let error () = unsupportedPattern p
573:     "smtv2: you must compile nested pattern-matching" in
574:   match p.pat_node with
575:   | Pwild ->
576:      let wild = create_vsymbol (id_fresh "wildcard") ty in
577:      fprintf fmt "@[<hv2>(%a %a)@]" (print_var info) wild (pr info) t
578:   | Papp(cs,[]) ->
579:      fprintf fmt "@[<hv2>(%a %a)@]" (print_ident info) cs.ls_name (pr info) t;
580:   | Papp(cs,args) ->
581:      let args = List.map (function
582:        | {pat_node = Pvar v} -> v | _ -> error ()) args in
583:      fprintf fmt "@[<hv2>(@[<hv2>(%a %a)@] %a)@]"
584:        (print_ident info) cs.ls_name (print_list space (print_var info)) args
585:        (pr info) t
586:   | _ -> error ()
587: 
588: and print_boolean_branches info subject pr fmt bl =
589:   let error () = unsupportedTerm subject
590:     "smtv2: bad pattern-matching on Boolean (compile_match missing?)"
591:   in
592:   match bl with
593:   | [br1 ; br2] ->
594:     let (p1,t1) = t_open_branch br1 in
595:     let (_p2,t2) = t_open_branch br2 in
596:     begin
597:       match p1.pat_node with
598:       | Papp(cs,_) ->
599:         let t1, t2 = if ls_equal cs fs_bool_true then t1, t2 else t2, t1 in
600:         fprintf fmt "@[<hv2>(ite %a %a %a)@]"
601:           (print_term info) subject
602:           (pr info) t1
603:           (pr info) t2
604:       | _ -> error ()
605:     end
606:   | _ -> error ()
607: 
608: and print_branches info subject pr fmt bl = match bl with
609:   | [] -> assert false
610:   | br::bl ->
611:       let (p,t) = t_open_branch br in
612:       let error () = unsupportedPattern p
613:         "smtv2: you must compile nested pattern-matching" in
614:       match p.pat_node with
615:       | Pwild -> pr info fmt t
616:       | Papp (cs,args) ->
617:           let args = List.map (function
618:             | {pat_node = Pvar v} -> v | _ -> error ()) args in
619:           if bl = [] then print_branch info subject pr fmt (cs,args,t)
620:           else
621:             begin match info.info_version with
622:               | V20 (* It was not defined at that time in the standard *) ->
623:                   fprintf fmt "@[<hv2>(ite (is-%a %a) %a %a)@]"
624:               | V26 | V26Par ->
625:                   fprintf fmt "@[<hv2>(ite ((_ is %a) %a) %a %a)@]"
626:             end
627:               (print_ident info) cs.ls_name (print_var info) subject
628:               (print_branch info subject pr) (cs,args,t)
629:               (print_branches info subject pr) bl
630:       | _ -> error ()
